-- Hardening da Fase 4: token inválido nunca pode cair em uma RPC administrativa.
-- Renomeamos as implementações já aplicadas e deixamos wrappers com validação explícita.
alter function public.app_admin_listar_ferias(text) rename to app_admin_listar_ferias_legacy;
alter function public.app_admin_criar_ferias(text,uuid,date,date,date,date,text,text) rename to app_admin_criar_ferias_legacy;
alter function public.app_admin_atualizar_ferias(text,uuid,date,date,text,text) rename to app_admin_atualizar_ferias_legacy;
alter function public.app_admin_listar_afastamentos(text) rename to app_admin_listar_afastamentos_legacy;
alter function public.app_admin_criar_afastamento(text,uuid,text,date,date,text,text) rename to app_admin_criar_afastamento_legacy;
alter function public.app_admin_atualizar_afastamento(text,uuid,date,text,text) rename to app_admin_atualizar_afastamento_legacy;
alter function public.app_admin_registrar_admissao(text,uuid,date,text,text,numeric,numeric,boolean) rename to app_admin_registrar_admissao_legacy;
alter function public.app_admin_demitir_funcionario(text,uuid,date,text) rename to app_admin_demitir_funcionario_legacy;
alter function public.app_admin_reintegrar_funcionario(text,uuid,date) rename to app_admin_reintegrar_funcionario_legacy;

create function public.app_admin_listar_ferias(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_listar_ferias_legacy(p_token); end; $$;
create function public.app_admin_criar_ferias(p_token text,p_funcionario_id uuid,p_periodo_aquisitivo_inicio date,p_periodo_aquisitivo_fim date,p_inicio date,p_fim date,p_status text default 'agendada',p_observacoes text default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_criar_ferias_legacy(p_token,p_funcionario_id,p_periodo_aquisitivo_inicio,p_periodo_aquisitivo_fim,p_inicio,p_fim,p_status,p_observacoes); end; $$;
create function public.app_admin_atualizar_ferias(p_token text,p_id uuid,p_inicio date,p_fim date,p_status text,p_observacoes text default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_atualizar_ferias_legacy(p_token,p_id,p_inicio,p_fim,p_status,p_observacoes); end; $$;
create function public.app_admin_listar_afastamentos(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_listar_afastamentos_legacy(p_token); end; $$;
create function public.app_admin_criar_afastamento(p_token text,p_funcionario_id uuid,p_tipo text,p_inicio date,p_fim date,p_motivo text default null,p_status text default 'ativo') returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_criar_afastamento_legacy(p_token,p_funcionario_id,p_tipo,p_inicio,p_fim,p_motivo,p_status); end; $$;
create function public.app_admin_atualizar_afastamento(p_token text,p_id uuid,p_fim date,p_motivo text,p_status text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_atualizar_afastamento_legacy(p_token,p_id,p_fim,p_motivo,p_status); end; $$;
create function public.app_admin_registrar_admissao(p_token text,p_funcionario_id uuid,p_data_admissao date,p_tipo_vinculo text default null,p_cargo text default null,p_valor_mensal numeric default null,p_valor_diaria numeric default null,p_registrado boolean default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_registrar_admissao_legacy(p_token,p_funcionario_id,p_data_admissao,p_tipo_vinculo,p_cargo,p_valor_mensal,p_valor_diaria,p_registrado); end; $$;
create function public.app_admin_demitir_funcionario(p_token text,p_funcionario_id uuid,p_data_demissao date,p_motivo text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_demitir_funcionario_legacy(p_token,p_funcionario_id,p_data_demissao,p_motivo); end; $$;
create function public.app_admin_reintegrar_funcionario(p_token text,p_funcionario_id uuid,p_data_admissao date) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.usuario_id is null or v.perfil not in ('admin','administrador') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return public.app_admin_reintegrar_funcionario_legacy(p_token,p_funcionario_id,p_data_admissao); end; $$;

grant execute on function public.app_admin_listar_ferias(text) to anon,authenticated;
grant execute on function public.app_admin_criar_ferias(text,uuid,date,date,date,date,text,text) to anon,authenticated;
grant execute on function public.app_admin_atualizar_ferias(text,uuid,date,date,text,text) to anon,authenticated;
grant execute on function public.app_admin_listar_afastamentos(text) to anon,authenticated;
grant execute on function public.app_admin_criar_afastamento(text,uuid,text,date,date,text,text) to anon,authenticated;
grant execute on function public.app_admin_atualizar_afastamento(text,uuid,date,text,text) to anon,authenticated;
grant execute on function public.app_admin_registrar_admissao(text,uuid,date,text,text,numeric,numeric,boolean) to anon,authenticated;
grant execute on function public.app_admin_demitir_funcionario(text,uuid,date,text) to anon,authenticated;
grant execute on function public.app_admin_reintegrar_funcionario(text,uuid,date) to anon,authenticated;
